/**
 * Verified creator database — single source of truth for the leaderboard,
 * search, review queue and directory surfaces.
 *
 * The database itself lives in `data/creators.db.json` and is generated by
 * `scripts/import-cr-figures.mjs` from the LIVE officialchadrankings.com
 * PublicFigure dataset, then enriched by `scripts/merge-verification.mjs`
 * with external identity corroboration. Nothing in this file invents a
 * person, a rank, a photo or a statistic.
 */
import db from "../data/creators.db.json";

export type VerificationStatus = "verified" | "needs_verification" | "disputed" | "rejected";

export interface CreatorRecord {
  id: string;
  displayName: string;
  alias: string | null;
  realName: string | null;
  category: string | null;
  rankTitle: string | null;
  tags: string[];
  rank: number | null;
  previousRank: number | null;
  influenceScore: number | null;
  rankChangeReason: string | null;
  specialBadge: string | null;
  communityVotes: number | null;
  rankingSource: string;
  rankingSourceUrl: string;
  rankingImportedAt: string;
  shortBio: string | null;
  detailedDescription: string | null;
  imageUrl: string | null;
  imageSourceUrl: string | null;
  imageLicenseOrPermission: string | null;
  verificationStatus: VerificationStatus;
  lastVerifiedAt: string | null;
  verificationNotes: string | null;
  sourceProfileUrl: string | null;
  socialProfiles: string[];
  isRoleRecord: boolean;
  importFlags: string[];
}

export const CREATORS = (db as unknown as { records: CreatorRecord[]; meta: ImportMeta }).records;
export const IMPORT_META = db.meta;

/** Ranks the official board publishes: 1..100 (mystery slots live beyond 100). */
export const BOARD_MAX = 100;
/**
 * Strict mode: only externally-verified identities render on the public
 * board. Default off — every public record is still verbatim from the live
 * official source and carries an explicit verification chip; flip to true
 * to restrict the public board to fully verified records.
 */
export const STRICT_BOARD = false;

const onBoard = (c: CreatorRecord) =>
  !c.isRoleRecord && Number.isFinite(c.rank) && (c.rank as number) >= 1 && (c.rank as number) <= BOARD_MAX;

/** verbatim board (ranks 1..100, role slots excluded) */
export function boardCreators(): CreatorRecord[] {
  return CREATORS.filter(onBoard).sort((a, b) => (a.rank as number) - (b.rank as number));
}

/** what the public leaderboard may render */
export function publicLeaderboard(): CreatorRecord[] {
  const board = boardCreators();
  return STRICT_BOARD ? board.filter((c) => c.verificationStatus === "verified") : board;
}

/** admin review queue: everything not cleared for public display */
export function reviewQueue(): CreatorRecord[] {
  return CREATORS.filter((c) => c.verificationStatus !== "verified").sort(
    (a, b) => (a.rank ?? 999) - (b.rank ?? 999),
  );
}

/** ext, verified creators from the separate research database (unranked) */
export function verifiedDirectory(): CreatorRecord[] {
  return CREATORS.filter((c) => c.verificationStatus === "verified" && !onBoard(c) && !c.isRoleRecord);
}

export type Movement = { figure: CreatorRecord; delta: number };

/** risers/droppers derived from the source's published previous_rank */
export function movements(): { risers: Movement[]; droppers: Movement[]; stable: number } {
  const rows = boardCreators();
  const mv = rows
    .filter((c) => Number.isFinite(c.previousRank) && Number.isFinite(c.rank))
    .map((c) => ({ figure: c, delta: (c.previousRank as number) - (c.rank as number) }));
  return {
    risers: mv.filter((m) => m.delta > 0).sort((a, b) => b.delta - a.delta),
    droppers: mv.filter((m) => m.delta < 0).sort((a, b) => a.delta - b.delta),
    stable: mv.length - mv.filter((m) => m.delta !== 0).length,
  };
}

/** dataset facts only — no fabricated statistics */
export function datasetStats() {
  const { risers, droppers, stable } = movements();
  return {
    board: boardCreators().length,
    verified: CREATORS.filter((c) => c.verificationStatus === "verified" && !c.isRoleRecord).length,
    pending: CREATORS.filter((c) => c.verificationStatus === "needs_verification").length,
    disputed: CREATORS.filter((c) => c.verificationStatus === "disputed").length,
    rejected: CREATORS.filter((c) => c.verificationStatus === "rejected").length,
    withPhotos: CREATORS.filter((c) => c.imageUrl && !c.isRoleRecord).length,
    movers: risers.length + droppers.length,
    stable,
    importedAt: IMPORT_META.importedAt,
    source: IMPORT_META.source,
  };
}

export function findCreator(name: string): CreatorRecord | undefined {
  const n = name.trim().toLowerCase();
  return CREATORS.find((c) => c.displayName.toLowerCase() === n);
}
